import heapq


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0

    coords = sorted({t for s, e, _ in jobs for t in (s, e)})
    idx = {t: i for i, t in enumerate(coords)}
    m = len(coords)

    adj: list[list[list[int]]] = [[] for _ in range(m)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        adj[u].append([v, cap, cost, len(adj[v])])
        adj[v].append([u, 0, -cost, len(adj[u]) - 1])

    for i in range(m - 1):
        add_edge(i, i + 1, k, 0)

    for s, e, pay in jobs:
        add_edge(idx[s], idx[e], 1, -pay)

    INF = 10**18
    pot = [INF] * m
    pot[0] = 0
    for u in range(m):
        pu = pot[u]
        if pu == INF:
            continue
        for v, cap, cost, _ in adj[u]:
            if cap > 0 and pu + cost < pot[v]:
                pot[v] = pu + cost

    source = 0
    sink = m - 1
    flow_left = k
    total_cost = 0

    while flow_left > 0:
        dist = [INF] * m
        dist[source] = 0
        parent_v = [-1] * m
        parent_e = [-1] * m
        pq: list[tuple[int, int]] = [(0, source)]

        while pq:
            d, u = heapq.heappop(pq)
            if d != dist[u]:
                continue
            pu = pot[u]
            for ei, (v, cap, cost, _) in enumerate(adj[u]):
                if cap > 0:
                    nd = d + cost + pu - pot[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        parent_v[v] = u
                        parent_e[v] = ei
                        heapq.heappush(pq, (nd, v))

        if dist[sink] == INF:
            break

        for i in range(m):
            if dist[i] < INF:
                pot[i] += dist[i]

        if pot[sink] >= 0:
            break

        push = flow_left
        v = sink
        while v != source:
            u = parent_v[v]
            ei = parent_e[v]
            if adj[u][ei][1] < push:
                push = adj[u][ei][1]
            v = u

        v = sink
        while v != source:
            u = parent_v[v]
            ei = parent_e[v]
            edge = adj[u][ei]
            edge[1] -= push
            adj[v][edge[3]][1] += push
            v = u

        flow_left -= push
        total_cost += push * pot[sink]

    return -total_cost
